import { ganttOptions } from "@owlky/core";
import { Gantt, type GanttProps } from "@owlky/react";
import type { ReactGroup } from "../../helpers/groups.js";
import type { GroupFiles } from "../shared/snippets.js";
import { type GanttExample, ganttExamples } from "./gantt-data.js";

/** Story groups: the same data as the HTML snippets (generated by `gantt-snippets.mjs`). */
export const ganttStories: Record<string, ReactGroup[]> = Object.fromEntries(
  Object.entries(ganttExamples).map(([story, { groups }]) => [
    story,
    groups.map(({ title, props }) => ({ title, content: <Gantt {...props} /> })),
  ]),
);

export const GANTT_FILES: Record<string, GroupFiles> = Object.fromEntries(
  Object.entries(ganttExamples).map(([story, { groups }]) => [
    story,
    groups.map(({ title, file }) => [title, file] as const),
  ]),
);

/** Values as JSX attribute text: strings quoted, the rest as compact JSON. */
const value = (data: unknown) =>
  typeof data === "string" ? JSON.stringify(data) : `{${JSON.stringify(data)}}`;

const element = ({ tasks: _tasks, ...props }: GanttProps, indent: string) => {
  const attributes = [
    `${indent}  tasks={tasks}`,
    ...Object.entries(props).map(([key, data]) =>
      data === true ? `${indent}  ${key}` : `${indent}  ${key}=${value(data)}`,
    ),
  ].join("\n");
  return `${indent}<Gantt\n${attributes}\n${indent}/>`;
};

/** The Code panel source of an example: the tasks as a constant, then the Gantt. */
export function ganttCode({ title, groups }: GanttExample): string {
  const name = `${title.replace(/(^|\s)(\w)/g, (_, __, c: string) => c.toUpperCase()).replace(/\W/g, "")}Gantt`;
  const tasks = (groups[0]?.props.tasks ?? [])
    .map((task) => `  ${JSON.stringify(task)},`)
    .join("\n");
  const body =
    groups.length > 1
      ? `    <>\n${groups.map((group) => element(group.props, "      ")).join("\n")}\n    </>`
      : element((groups[0] as { props: GanttProps }).props, "    ");
  return `import { Gantt, type GanttTask } from "@owlky/react";

const tasks: GanttTask[] = [
${tasks}
];

export function ${name}() {
  return (
${body}
  );
}`;
}

/** Story Controls shared by the React and HTML stories (ADR-0015). */
export const GANTT_CONTROLS = {
  schema: ganttOptions,
  keys: ["rowHeight", "showToday", "showNonWorkingDays", "columnLines"],
} as const;
